"use client";

import Link from "next/link";
import { useState, useEffect } from "react";
import { useRouter } from "next/navigation";

export default function Navbar() {
  const [user, setUser] = useState(null);
  const [openMenu, setOpenMenu] = useState(false);
  const router = useRouter();

  useEffect(() => {
    const token = localStorage.getItem("token");
    if (!token) return;

    try {
      const payload = JSON.parse(atob(token.split(".")[1]));
      setUser({ role: payload.role, phone: payload.phone });
    } catch {
      setUser(null);
    }
  }, []);

  const logout = () => {
    localStorage.removeItem("token");
    setUser(null);
    router.push("/");
  };

  return (
    <nav style={navStyle}>
      <div style={navContainer}>
        {/* LEFT: Brand */}
        <div style={brandWrap}>
          <Link href="/" style={logoStyle}>
            EcoLoop
          </Link>
          <span style={taglineStyle}>Smart Waste. Real Impact.</span>
        </div>

        {/* CENTER: Primary navigation */}
        <div style={menuStyle}>
          <Link href="/how-it-works" style={linkStyle}>
            How it Works
          </Link>

          {user && (
            <Link href="/dashboard" style={linkStyle}>
              Dashboard
            </Link>
          )}

          {user?.role === "household" && (
            <Link href="/household/waste" style={primaryAction}>
              Post Waste
            </Link>
          )}

          {user?.role === "company" && (
            <Link href="/company/matches" style={primaryAction}>
              Find Waste
            </Link>
          )}
        </div>

        {/* RIGHT: Auth / User */}
        <div style={rightStyle}>
          {!user && (
            <Link href="/auth" style={authButton}>
              Get Started
            </Link>
          )}

          {user && (
            <div style={{ position: "relative" }}>
              <button
                onClick={() => setOpenMenu(!openMenu)}
                style={userButtonStyle}
              >
                {user.phone}
              </button>

              {openMenu && (
                <div style={dropdownStyle}>
                  <Link href="/profile" style={dropdownItem}>
                    Profile
                  </Link>
                  <button onClick={logout} style={dropdownItem}>
                    Logout
                  </button>
                </div>
              )}
            </div>
          )}
        </div>
      </div>
    </nav>
  );
}

/* ===================== STYLES ===================== */

const navStyle = {
  position: "fixed",
  top: 0,
  width: "100%",
  background: "#ffffff",
  borderBottom: "1px solid #e5e7eb",
  zIndex: 100,
};

const navContainer = {
  maxWidth: "1200px",
  margin: "0 auto",
  display: "flex",
  alignItems: "center",
  justifyContent: "space-between",
  padding: "14px 20px",
};

const brandWrap = {
  display: "flex",
  flexDirection: "column",
};

const logoStyle = {
  fontWeight: 700,
  fontSize: "22px",
  color: "#16a34a",
  textDecoration: "none",
};

const taglineStyle = {
  fontSize: "11px",
  color: "#6b7280",
};

const menuStyle = {
  display: "flex",
  alignItems: "center",
  gap: "22px",
};

const linkStyle = {
  textDecoration: "none",
  color: "#374151",
  fontWeight: 500,
  fontSize: "14px",
};

const primaryAction = {
  textDecoration: "none",
  background: "#16a34a",
  color: "#ffffff",
  padding: "8px 14px",
  borderRadius: "8px",
  fontWeight: 600,
  fontSize: "14px",
};

const rightStyle = {
  display: "flex",
  alignItems: "center",
};

const authButton = {
  textDecoration: "none",
  border: "1px solid #16a34a",
  color: "#16a34a",
  padding: "8px 14px",
  borderRadius: "8px",
  fontWeight: 600,
  fontSize: "14px",
};

const userButtonStyle = {
  background: "#16a34a",
  color: "#ffffff",
  border: "none",
  padding: "8px 14px",
  borderRadius: "999px",
  cursor: "pointer",
  fontSize: "13px",
};

const dropdownStyle = {
  position: "absolute",
  top: "120%",
  right: 0,
  background: "#ffffff",
  boxShadow: "0 12px 30px rgba(0,0,0,0.12)",
  borderRadius: "10px",
  overflow: "hidden",
  minWidth: "160px",
};

const dropdownItem = {
  display: "block",
  padding: "12px 16px",
  fontSize: "14px",
  textAlign: "left",
  background: "transparent",
  border: "none",
  width: "100%",
  cursor: "pointer",
  color: "#111827",
};
